#include "harness.h"

#ifndef TX_MAX_SECURE_CONTEXTS
#define TX_MAX_SECURE_CONTEXTS      32U
#endif

#ifdef TX_TIMER_PROCESS_IN_ISR
#define AVAILABLE_CONTEXTS         TX_MAX_SECURE_CONTEXTS
#define TIMER_STACK_STATUS         TX_CALLER_ERROR
#else
#define AVAILABLE_CONTEXTS         (TX_MAX_SECURE_CONTEXTS - 1U)
#define TIMER_STACK_STATUS         TX_SUCCESS
#endif

#define TEST_THREAD_COUNT           (AVAILABLE_CONTEXTS + 1U)
#define NONSECURE_STACK_WORDS       128U
#define SMALL_SECURE_STACK          256UL
#define LARGE_SECURE_STACK          1024UL
#define TIMER_WAIT_TICKS            20UL

static TX_THREAD    test_threads[TEST_THREAD_COUNT];
static ULONG        test_stacks[TEST_THREAD_COUNT][NONSECURE_STACK_WORDS];
static TX_TIMER     test_timer;
static volatile UINT timer_allocate_status = TX_NOT_DONE;
static volatile UINT timer_free_status = TX_NOT_DONE;

/* The test threads stay suspended while the manager allocates their secure stacks.  */
static VOID test_thread_entry(ULONG thread_input)
{
    (VOID) thread_input;
}

/* Create one suspended thread to hold a secure stack.  */
static UINT create_test_thread(UINT index)
{
    UINT status;

    status = tx_thread_create(&test_threads[index], "Secure stack test thread", test_thread_entry, 0UL,
                              test_stacks[index], sizeof(test_stacks[index]), 2U, 2U, TX_NO_TIME_SLICE, TX_DONT_START);
    harness_expect("create secure stack test thread", (ULONG) status, (ULONG) TX_SUCCESS);
    return(status);
}

/* Check that an application can allocate and release a stack during kernel initialization.  */
VOID harness_test_initialize(VOID)
{
    if (create_test_thread(0U) == TX_SUCCESS)
    {
        harness_expect("allocate a secure stack at startup",
                       (ULONG) tx_thread_secure_stack_allocate(&test_threads[0], SMALL_SECURE_STACK), (ULONG) TX_SUCCESS);
        harness_expect("free a secure stack at startup",
                       (ULONG) tx_thread_secure_stack_free(&test_threads[0]), (ULONG) TX_SUCCESS);
    }
}

/* Record whether the timer's execution context permits secure stack services.  */
static VOID test_timer_expire(ULONG timer_input)
{
    (VOID) timer_input;
    timer_allocate_status = tx_thread_secure_stack_allocate(&test_threads[0], SMALL_SECURE_STACK);
    timer_free_status = tx_thread_secure_stack_free(&test_threads[0]);
}

/* Fill the heap or context pool, then verify that releasing one stack allows a retry.  */
static VOID check_stack_limit(ULONG stack_size, UINT minimum_count, UINT maximum_count)
{
    UINT count;
    UINT index;
    UINT status = TX_SUCCESS;

    for (count = 0U; count < TEST_THREAD_COUNT; count++)
    {
        status = tx_thread_secure_stack_allocate(&test_threads[count], stack_size);
        if (status != TX_SUCCESS)
        {
            break;
        }
    }

    harness_expect("secure stack allocation at capacity", (ULONG) status, (ULONG) TX_NO_MEMORY);
    harness_value("allocated stacks", (ULONG) count);
    harness_expect("secure stack capacity",
                   ((count >= minimum_count) && (count <= maximum_count)) ? (ULONG) TX_TRUE : (ULONG) TX_FALSE,
                   (ULONG) TX_TRUE);
    if ((count > 0U) && (count < TEST_THREAD_COUNT))
    {
        harness_expect("free a secure stack at capacity",
                       (ULONG) tx_thread_secure_stack_free(&test_threads[0]), (ULONG) TX_SUCCESS);
        status = tx_thread_secure_stack_allocate(&test_threads[count], stack_size);
        harness_expect("retry secure stack allocation", (ULONG) status, (ULONG) TX_SUCCESS);
        if (status == TX_SUCCESS)
        {
            harness_expect("free the retried secure stack",
                           (ULONG) tx_thread_secure_stack_free(&test_threads[count]), (ULONG) TX_SUCCESS);
        }
        for (index = 1U; index < count; index++)
        {
            harness_expect("free a secure stack",
                           (ULONG) tx_thread_secure_stack_free(&test_threads[index]), (ULONG) TX_SUCCESS);
        }
    }
}

VOID harness_test(VOID)
{
    UINT index;
    UINT status;
    ULONG start;

    harness_print("Secure stacks: heap and context exhaustion, reuse, and timer calls\n");

    for (index = 1U; index < TEST_THREAD_COUNT; index++)
    {
        if (create_test_thread(index) != TX_SUCCESS)
        {
            return;
        }
    }

    harness_print("Exhaust the secure heap with large stacks\n");
    check_stack_limit(LARGE_SECURE_STACK, 1U, AVAILABLE_CONTEXTS - 1U);
    harness_print("Exhaust the secure context pool with small stacks\n");
    check_stack_limit(SMALL_SECURE_STACK, AVAILABLE_CONTEXTS, AVAILABLE_CONTEXTS);

    status = tx_timer_create(&test_timer, "Secure stack timer", test_timer_expire, 0UL, 1UL, 0UL, TX_AUTO_ACTIVATE);
    harness_expect("create secure stack test timer", (ULONG) status, (ULONG) TX_SUCCESS);
    if (status == TX_SUCCESS)
    {
        start = tx_time_get();
        while ((timer_free_status == TX_NOT_DONE) && ((tx_time_get() - start) < TIMER_WAIT_TICKS))
        {
            (VOID) tx_thread_sleep(1UL);
        }
        harness_expect("secure stack allocation from timer", (ULONG) timer_allocate_status, (ULONG) TIMER_STACK_STATUS);
        harness_expect("secure stack free from timer", (ULONG) timer_free_status, (ULONG) TIMER_STACK_STATUS);
        harness_expect("delete secure stack test timer", (ULONG) tx_timer_delete(&test_timer), (ULONG) TX_SUCCESS);
    }
}
